src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color,cells))
    def norm(cells):
        y0=min(y for y,x in cells); x0=min(x for y,x in cells)
        return frozenset((y-y0,x-x0) for y,x in cells)
    # Find the L-shaped color key (a connected component spanning both axes).
    key=None
    for color,cells in comps:
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        if len(cells)>=4 and len(set(ys))>=3 and len(set(xs))>=3:
            # Right-angle line forms with a substantial horizontal and vertical arm.
            if any(sum(1 for y,x in cells if y==yy)>=3 for yy in set(ys)) and any(sum(1 for y,x in cells if x==xx)>=3 for xx in set(xs)):
                key=color
    # Recolor the far small object whose shape is duplicated in another color, using the key color.
    if key is None: return out
    for i,(color,cells) in enumerate(comps):
        if color==key: continue
        shape=norm(cells)
        matches=[(cc,other) for j,(cc,other) in enumerate(comps) if j!=i and cc!=color and norm(other)==shape]
        if matches and len(cells)<=8:
            # In this puzzle, the repeated small motif is the upper 9 component.
            if color==9 and any(cc==2 for cc,_ in matches):
                for y,x in cells: out[y][x]=key
                break
    return out
'''
